import { driver, expect } from '@wdio/globals';
import { byTextContains } from '../../helpers/ui.ts';
import { skipWith } from '../_lib/app-0710.ts';
import { goHome, nodes } from '../_lib/readiness-1910.ts';
import { saveShot, openTehilimScreen, segment, AVOT_OFF_SEASON, AVOT_OFF_SEASON_FULL, AVOT_RETURN_OLD } from '../_lib/app-2510.ts';

/** Точно вне сезона: 6 октября … 25 марта (как q-15). */
function surelyOffSeason(d = new Date()) {
  const m = d.getMonth() + 1; const day = d.getDate();
  return (m === 10 && day >= 6) || m === 11 || m === 12 || m === 1 || m === 2 || (m === 3 && day <= 25);
}

describe('26.10 — текст «פרקי אבות» вне сезона (#70ef78)', () => {
  afterEach(async () => { await goHome().catch(() => {}); });

  it('TH-05a «ברכות» → «פרקי אבות» сегодня вне сезона: абзац целиком «…הסימון יחזור בשבוע של השבת הראשונה שאחרי פסח.», старого «…יחזור בשבת הראשונה…» нет, меток «פרק השבוע» нет #70ef78 #30e340e0 @prod-safe', async function () {
    if (driver.isAndroid) skipWith(this, '#70ef78 проверен на iPhone и в вебе; Android не проверялся');
    if (!surelyOffSeason()) skipWith(this, 'сейчас может быть сезон פרקי אבות — даты проверяет веб-тест th-06 (подмена часов)');
    expect(await openTehilimScreen()).toBe('ברכות');
    await segment('פרקי אבות');
    await expect(byTextContains(AVOT_OFF_SEASON)).toBeExisting({ wait: 15000 });
    // Текст целиком — один узел (label абзаца), без обрезки и без старой формулировки.
    const ns = await nodes();
    const para = ns.filter((n) => n.label.includes(AVOT_OFF_SEASON)).map((n) => n.label.trim());
    expect(para).toContain(AVOT_OFF_SEASON_FULL);
    expect(ns.some((n) => n.label.includes(AVOT_RETURN_OLD))).toBe(false);
    // Шесть карточек глав, ни на одной нет «פרק השבוע».
    const cards = ns.filter((n) => /^פרקי אבות [א-ו]׳ — /.test(n.label));
    expect(new Set(cards.map((n) => n.label.split(' ')[2])).size).toBe(6);
    expect(cards.filter((n) => n.label.includes('פרק השבוע')).map((n) => n.label)).toEqual([]);
    await saveShot('TH-05a-avot-off-season-70ef78.png');
    await segment('תהילים');
  });
});
